-- Exact DDL Hibernate 7.2.12 generated for the Spring backend's entities (PostgreSQLDialect),
-- produced offline from the compiled entities. Used to prove the Drizzle baseline is a no-op on it.
create table app_user (onboarding_complete boolean default false not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, id uuid not null, role varchar(16) default 'USER' not null check ((role in ('USER','ADMIN'))), email varchar(255) not null unique, google_sub varchar(255) not null unique, name varchar(255) not null, primary key (id));
create table candidate_profile (created_at timestamp(6) with time zone not null, resume_parsed_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, id uuid not null, user_id uuid not null unique, achievements jsonb not null, detected_links jsonb not null, education jsonb not null, email varchar(255), experience jsonb not null, full_name varchar(255), headline varchar(255), location varchar(255), phone varchar(255), projects jsonb not null, resume_filename varchar(255), skills jsonb not null, target_role varchar(255), primary key (id));
create table companies (tier integer, created_at timestamp(6) with time zone not null, id uuid not null, company_size varchar(255), headquarter_location varchar(255), logo_url varchar(255), name varchar(255) not null, slug varchar(255) not null unique, primary key (id));
create table company_role_configs (enabled boolean not null, round_count integer, created_at timestamp(6) with time zone not null, id uuid not null, level varchar(16) not null, company varchar(255) not null, jd_description text, jd_title varchar(255), jd_url varchar(255), requirements text, responsibilities text, role varchar(255) not null, tech_stack text, primary key (id), constraint uq_company_role_level unique (company, role, level));
create table github_connection (connected_at timestamp(6) with time zone not null, last_refreshed_at timestamp(6) with time zone, id uuid not null, status varchar(16) check ((status in ('SYNCING','SYNCED','FAILED','DEGRADED'))), user_id uuid not null unique, access_token_enc varchar(2048) not null, github_login varchar(255) not null, scope varchar(255) not null, primary key (id));
create table interview_sessions (duration_s integer, live_score_final float(53), created_at timestamp(6) with time zone not null, live_ended_at timestamp(6) with time zone, live_started_at timestamp(6) with time zone, scheduled_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, candidate_id uuid not null, id uuid not null, job_description_id uuid not null, level varchar(16) not null, status varchar(24) not null check ((status in ('SCHEDULED','PREP_QUEUED','PREP_READY','PREP_FAILED','LIVE_IN_PROGRESS','COMPLETED','ABORTED_TECHNICAL'))), ended_reason varchar(32), round_type varchar(32) not null check ((round_type in ('dsa','system-design','hiring-manager','lld','behavioural'))), specialization varchar(32), timezone varchar(64) not null, company varchar(255) not null, input_hash varchar(255), livekit_room varchar(255), outcome jsonb, plan_version varchar(255), prep_error varchar(255), role varchar(255) not null, primary key (id));
create table job_descriptions (active boolean not null, created_at timestamp(6) with time zone not null, id uuid not null, level varchar(16) not null, source varchar(16) not null, specialization varchar(32), company varchar(255) not null, description text, role varchar(255) not null, source_url varchar(255), tech_stack text, title varchar(255) not null, primary key (id));
create table leetcode_connection (connected_at timestamp(6) with time zone not null, last_refreshed_at timestamp(6) with time zone, id uuid not null, status varchar(16) not null check ((status in ('SYNCING','SYNCED','FAILED','DEGRADED'))), user_id uuid not null unique, username varchar(255) not null, primary key (id));
create table profile_fragment (version integer not null, fetched_at timestamp(6) with time zone not null, id uuid not null, user_id uuid not null, source varchar(32) not null check ((source in ('GITHUB','RESUME','LEETCODE','LINKEDIN','X'))), content_hash varchar(64) not null, data jsonb not null, primary key (id), constraint uq_fragment_user_source unique (user_id, source));
create table refresh_token (expires_at timestamp(6) with time zone not null, revoked_at timestamp(6) with time zone, id uuid not null, user_id uuid not null, token_hash varchar(128) not null unique, primary key (id));
create index idx_session_candidate on interview_sessions (candidate_id);
create index idx_session_status_scheduled on interview_sessions (status, scheduled_at);
create index idx_jd_company_level on job_descriptions (company, level);
alter table if exists refresh_token add constraint FK5wkt2p042y3lwltk29cvpxuh foreign key (user_id) references app_user;
